/*selectMasterMdCdCompanyAddressNextcodeVal*/

SELECT NVL(MAX(TO_NUMBER(CODE1)) +1,'1')			 				 
FROM ICOMCOD3
WHERE BUYER = #{irs_no}
AND TYPE = 'CP_ADDR'

