/*deleteMasterMdCdCompanyAddressPop*/

UPDATE ICOMCOD3
SET FLAG = 'N'
WHERE BUYER = #{irs_no}
AND CODE1 = #{code1}
AND TYPE = 'CP_ADDR'
AND FLAG = 'Y'


/*saveMasterMdCdCompanyAddressPop*/

UPDATE ICOMCOD3
SET TEXT1 = #{text1}
WHERE BUYER = #{irs_no}
AND CODE1 = #{code1}			
AND TYPE = 'CP_ADDR'
AND FLAG = 'Y'
